import React, { useState } from 'react'
import './App.css';
import Preview from './components/preview';

function App() {

  const [notes, setnotes] = useState([])
  const [title, setTitle] = useState('')
  const [content, setContent] = useState('')
  const [selectedNote, setSelectedNote] = useState(null)
  const [creating, setCreating] = useState(false)
  const [editing, setEditing] = useState(false)

  const saveNoteHandler = ()=>{
    const note = {
      id: new Date(),
      title: title,
      content: content
    }
    const updateNote = [...notes,note]
    setnotes(updateNote)

    setCreating(false)
  }


  const getAddNote = () => {
    return (
      <div>
        <h2>إضافة ملاحظة جديدة</h2>
        <div>
          <input
            type="text"
            name="title"
            className="form-input mb-30"
            placeholder="العنوان"
            value={title}
            //لتغيير القيمة التي تظهر على الشاشه
            onChange={(e) => {setTitle(e.target.value)}}
          />

          <textarea
            rows="10"
            name="content"
            className="form-input"
            placeholder="النص"
            value={content}
            //لتغيير القيمة التي تظهر على الشاشه
            onChange={(e) => {setContent(e.target.value)}}
          />


          <a onClick={saveNoteHandler} href="#" className="button green">
            حفظ
          </a>
        </div>
      </div>
    );
  };

  const getPreview = () => {
    return (
      <div>
        <div className="note-operations">
          <a href="#">
            <i className="fa fa-pencil-alt" />
          </a>
          <a href="#">
            <i className="fa fa-trash" />
          </a>
        </div>
        <div>
          <h2>عنوان ملاحظة تجريبية</h2>
          <p>نص ملاحظة تجريبية</p>
        </div>
      </div>
    );
  };

  return (
    <div className="App">
      <div className="notes-section">
        <ul className="notes-list">
          <li className="note-item">ملاحظة رقم #1</li>
          <li className="note-item">ملاحظة رقم #2</li>
          <li className="note-item">ملاحظة رقم #3</li>
          <li className="note-item">ملاحظة رقم #4</li>
        </ul>
        <button className="add-btn" onClick={()=>{setCreating(true)}}>+</button>
      </div>
      <Preview className="preview-section">{creating? getAddNote():getPreview()}</Preview>
    </div>
  );
}

export default App;
